import { useEffect, useState, useCallback } from "react";
import config from "../config.json";

export default function Page() {
  const [images, setImages] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  // Función para cargar las imágenes
  const fetchImages = useCallback(async () => {
    try {
      const res = await fetch("/api/listupload");
      const data = await res.json();
      if (data.images) setImages(data.images);
    } catch (err) {
      console.error("Error cargando imágenes:", err);
    }
  }, []);

  // Carga inicial + refresco cada 10s
  useEffect(() => {
    fetchImages();
    const fetchInterval = setInterval(fetchImages, 10000); // cada 10s
    return () => clearInterval(fetchInterval);
  }, [fetchImages]);

  // Carrusel automático
  useEffect(() => {
    if (images.length === 0) return;

    const interval = setInterval(() => {
      setCurrentIndex(prevIndex => (prevIndex + 1) % images.length);
    }, 5000); // cambiar cada 5s

    return () => clearInterval(interval);
  }, [images]);

  return (
    <div
      style={{
        position: "relative",
        height: "100vh",
        width: "100vw",
        overflow: "hidden",
        color: "white",
      }}
    >
      {/* Video de fondo */}
      <video
        autoPlay
        loop
        muted
        playsInline
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          objectFit: "cover",
          zIndex: -1,
        }}
      >
        <source src={config.fondo} type="video/mp4" />
        Tu navegador no soporta videos.
      </video>

      {/* Contenido encima */}
      <div
        style={{
          position: "relative",
          zIndex: 1,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          height: "100%",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "3rem", color: config.colorTextoPrincipal }}>
          {config.textoPrincipal}
        </h1>
        <p
          style={{
            fontSize: "2rem",
            marginTop: "20px",
            color: config.colorTextoSecundario,
          }}
        >
          Escanea el QR en tu mesa
        </p>

        {/* Carrusel de fotos */}
        <div
          style={{
            position: "relative",
            width: "300px",
            height: "300px",
            marginTop: "30px",
          }}
        >
          {images.length === 0 ? (
            <p>No hay fotos subidas aún.</p>
          ) : (
            <img
              key={currentIndex}
              src={images[currentIndex]}
              alt={`Foto ${currentIndex + 1}`}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                borderRadius: "8px",
                boxShadow: "0 2px 6px rgba(0,0,0,0.3)",
                transition: "opacity 0.5s ease-in-out",
              }}
            />
          )}
        </div>

        <a
          href={config.urlUpload}
          style={{
            marginTop: "30px",
            padding: "10px 20px",
            background: "#0070f3",
            color: "white",
            borderRadius: "5px",
            textDecoration: "none",
          }}
        >
          ⚙️ Administrar Fotos
        </a>
      </div>
    </div>
  );
}
